const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const s = j; // settings are merged into the item
  const src = (j.body && typeof j.body === 'object') ? j.body : j;
  const pick = keys => { for (const k of keys) if (src[k] !== undefined && src[k] !== null && src[k] !== '') return src[k]; return ''; };
  const client = String(pick(['client_name', 'Client Name'])).trim();
  if (!client) continue;
  let phone = String(pick(['client_whatsapp', 'Client WhatsApp Number', 'whatsapp', 'phone'])).replace(/\D/g, '');
  if (phone.length === 10) phone = String(s.default_country_code || '91') + phone;
  const now = new Date();
  let due = new Date(pick(['due_date', 'Due Date']));
  if (isNaN(due)) due = new Date(now.getTime() + 7 * 864e5);
  const id = `DOC-${now.toISOString().slice(2, 10).replace(/-/g, '')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
  const type = String(pick(['compliance_type', 'Compliance Type']) || 'Compliance');
  const period = String(pick(['period', 'Period']));
  const firstGap = Number(s.first_reminder_after_days) || 2;
  out.push({ json: {
    request_id: id,
    created_at: now.toISOString(),
    client_name: client,
    client_email: String(pick(['client_email', 'Client Email'])).trim(),
    client_whatsapp: phone,
    compliance_type: type,
    period,
    due_date: due.toISOString().slice(0, 10),
    documents_required: list(pick(['documents_required', 'Documents Required'])),
    assigned_ca_email: String(pick(['assigned_ca_email', 'Assigned CA Email']) || s.team_email),
    notes: String(pick(['notes', 'Notes'])),
    next_reminder_at: new Date(now.getTime() + firstGap * 864e5).toISOString(),
    upload_link: `${String(s.n8n_base_url).replace(/\/$/, '')}/form/${s.upload_form_path}?request_id=${id}`,
    folder_name: `${client} - ${type} ${period} (${id})`,
  }});
}
return out;

