return $input.all().map((item, i) => {
  const p = plans[i].json;
  let a = item.json.message?.content ?? item.json.content ?? {};
  if (typeof a === 'string') { try { a = JSON.parse(a.replace(/```json|```/g, '').trim()); } catch (e) { a = {}; } }
  const first = String(p.client_name || '').split(' ')[0];
  const fallback = {
    friendly: [`This is a gentle reminder that we are still waiting for a few documents for your ${p.compliance_type} (${p.period}), due on ${fmtDate(p.due_date)}.`, 'Uploading takes only a couple of minutes using the button below.'],
    firm: [`Your ${p.compliance_type} for ${p.period} is due on ${fmtDate(p.due_date)}, and we cannot begin work until the pending documents are received.`, 'Please upload them at the earliest.'],
    urgent: [`The due date for your ${p.compliance_type} (${p.period}) was ${fmtDate(p.due_date)}. Further delay may attract late fees and interest.`, 'Please upload the pending documents today so we can file immediately.'],
  };
  const paras = Array.isArray(a.paragraphs) && a.paragraphs.length ? a.paragraphs : fallback[p.tone];
  const subject = a.subject || `${p.tone === 'urgent' ? 'Action required: ' : p.tone === 'firm' ? 'Reminder: ' : ''}documents for ${p.compliance_type} ${p.period}`;
  const color = p.tone === 'urgent' ? '#b91c1c' : p.tone === 'firm' ? '#a16207' : '#1d4ed8';
  const email_html = shell(s, `<div style="border-left:4px solid ${color};padding-left:12px">
