<p style="margin-bottom:0"><b>Your checklist</b> (due ${fmtDate(p.due_date)}):</p>
${checklist(p.required, new Set(p.received.map(x => x.toLowerCase())))}
${button(p.upload_link, `Upload ${p.pending.length} pending document${p.pending.length > 1 ? 's' : ''}`)}
<p>${esc(a.sign_off || 'Warm regards,')}<br>${esc(s.firm_name)}</p>`);
  const newStatus = p.escalate || p.prev_status.toLowerCase() === 'escalated' ? 'Escalated' : (p.received.length ? 'Partial' : 'Pending');
  const esc_html = shell(s, `<h2 style="color:#b91c1c">⚠️ Client needs a personal follow-up</h2>
<p><b>${esc(p.client_name)}</b> · ${esc(p.compliance_type)} ${esc(p.period)}<br>
Due ${fmtDate(p.due_date)} (${p.days_to_due < 0 ? Math.abs(p.days_to_due) + ' days overdue' : p.days_to_due + ' days left'}) · Reminder #${p.reminder_number}${p.final_notice ? ' (final automated reminder)' : ''}</p>
<p><b>Still pending:</b> ${esc(p.pending.join(', '))}<br><b>Received:</b> ${esc(p.received.join(', ') || 'nothing yet')}</p>
<p>📞 WhatsApp / phone: ${esc(p.client_whatsapp)} · ✉️ ${esc(p.client_email)}</p>
${p.drive_folder_link ? button(p.drive_folder_link, 'Open client folder') : ''}`);
  return { json: {
