const now = new Date(), DAY = 864e5;
const rows = $input.all().map(i => i.json).filter(r => r.request_id);
const days = r => { const d = new Date(r.due_date); return isNaN(d) ? null : Math.ceil((d - now) / DAY); };
const order = { escalated: 0, pending: 1, partial: 2, 'on hold': 3, complete: 4, cancelled: 5 };
