// Picks requests whose next reminder is due and decides tone, cadence and escalation
const s = $('Set Chaser Config').first().json;
const DAY = 864e5, now = new Date();
const maxR = Number(s.max_reminders) || 8, escAt = Number(s.escalate_after_reminders) || 3, base = Number(s.default_interval_days) || 3;
const out = [];
for (const item of $('Get All Requests1').all()) {
  const r = item.json;
  if (!r.request_id) continue;
  const status = String(r.status || 'Pending');
  if (['complete', 'cancelled', 'on hold'].includes(status.toLowerCase())) continue;
  const required = list(r.documents_required);
  const have = new Set(list(r.documents_received).map(x => x.toLowerCase()));
  const pending = required.filter(d => !have.has(d.toLowerCase()));
  if (!pending.length) continue;
  const next = r.next_reminder_at ? new Date(r.next_reminder_at) : new Date(0);
  if (!isNaN(next) && next > now) continue;
  const sent = Number(r.reminders_sent) || 0;
  if (sent >= maxR) continue;
  const due = new Date(r.due_date);
  const daysToDue = isNaN(due) ? 99 : Math.ceil((due - now) / DAY);
